/* BioCompute v0.2: offline-capable, dependency-free frontend. Safe DOM rendering via escaping.
   A React/TypeScript migration is planned; no CDN runtime is required for this milestone. */
const $ = (selector, root = document) => root.querySelector(selector);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr = esc;
const fmt = (n) => new Intl.NumberFormat().format(Number(n||0));
const bytes = (n) => {if(!n)return '—';let v=Number(n),i=0;while(v>=1024&&i<4){v/=1024;i++}return `${v.toFixed(i?1:0)} ${['B','KB','GB','TB','PB'][i]}`};
const date = x => x ? new Date(x).toLocaleString() : '—';
const shorten = (s,n=34) => String(s||'').length>n?String(s).slice(0,n-3)+'...':String(s||'');
const safeJSON = obj => JSON.stringify(obj).replace(/</g,'\\u003c');
