function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.info}</svg>`}
function badge(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`}
function statusBadge(s){const map={completed:'success',running:'info',queued:'warning',failed:'danger',interrupted:'warning',cancelled:'danger',online:'success',discovered:'warning'};return badge(s||'unknown',map[s]||'')}
function empty(symbol,title,description,cta=''){return `<div class="empty"><div class="empty-icon">${icon(symbol,25)}</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${cta}</div>`}
const appState={token:sessionStorage.getItem('bio-token')||'',route:'dashboard',data:null,nodes:[],pipelines:[],experiments:[],runs:[],graphs:[],system:null,search:'',wizard:null,experimentEdit:null,drawer:null,picker:null,modal:null,toast:[],cpuHistory:[0],runDetail:null,runLog:'',runLogOffset:0,artifacts:[],execution:null,executionRunId:'',studioMode:'design',registry:null,registryOpen:false,registryQuery:'',theme:localStorage.getItem('bio-theme')||'dark',studio:{nodes:[],edges:[],selected:null,connectFrom:null,name:'New workflow draft'},initialized:false};
document.documentElement.classList.toggle('light',appState.theme==='light');
async function api(endpoint, options={}){
  const headers={...(options.headers||{}),...(appState.token?{'Authorization':`Bearer ${appState.token}`}:{})};
  if(options.body && typeof options.body!=='string') {headers['Content-Type']='application/json';options.body=JSON.stringify(options.body)}
  let response;
  try {response=await fetch('/api'+endpoint,{...options,headers})}catch(err){throw new Error('Cannot reach BioCompute controller: '+err.message)}
  if(response.status===401){appState.token='';sessionStorage.removeItem('bio-token');render();throw new Error('Access token expired or invalid')}
  let result=await response.json().catch(()=>({}));
  if(!response.ok){let m=result.detail;if(typeof m==='object')m=JSON.stringify(m);throw new Error(m||`${response.status} ${response.statusText}`)}
  return result;
}
async function loadAll(){
  const [system,dashboard,nodes,pipelines,experiments,runs,graphs]=await Promise.all([
    api('/system'),api('/dashboard'),api('/nodes'),api('/pipelines'),api('/experiments'),api('/runs'),api('/studio/graphs')]);
  Object.assign(appState,{system,data:dashboard,nodes,pipelines,experiments,runs,graphs,initialized:true});
  const c=dashboard.controller?.details?.cpu_percent;
  if(c!==undefined) appState.cpuHistory=[...appState.cpuHistory.slice(-23),Math.max(0,Number(c))];
}
function notify(text,bad=false){const id=Date.now()+Math.random();appState.toast.push({id,text,bad});renderToasts();setTimeout(()=>{appState.toast=appState.toast.filter(t=>t.id!==id);renderToasts()},4800)}
function renderToasts(){let el=$('#toasts');if(el)el.innerHTML=appState.toast.map(t=>`<div class="toast ${t.bad?'bad':''}">${esc(t.text)}</div>`).join('')}
function button(action,text,kind='',extra=''){return `<button class="btn ${kind}" data-action="${esc(action)}" ${extra}>${text}</button>`}
const nav=[['dashboard','dashboard','Overview'],['nodes','network','Compute Nodes'],['pipelines','pipeline','Pipeline Library'],['experiments','flask','Experiments'],['studio','studio','Pipeline Studio'],['runs','jobs','Run Manager'],['settings','settings','Settings']];
function renderShell(){const route=appState.route;const current=nav.find(n=>n[0]===route);return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-logo">${icon('logo',26)}</div><div><strong>BioCompute</strong><small>SCIENCE, SCALED.</small></div></div><div class="nav-label">Workspace</div><nav class="nav-list">${nav.slice(0,6).map(([r,i,label])=>`<button class="nav-link ${r===route?'active':''}" data-action="navigate" data-route="${r}" title="${label}">${icon(i,19)}<span>${label}</span></button>`).join('')}</nav><div class="nav-grow"></div><div class="nav-label">System</div><nav class="nav-list">${nav.slice(6).map(([r,i,label])=>`<button class="nav-link ${r===route?'active':''}" data-action="navigate" data-route="${r}" title="${label}">${icon(i,19)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-node"><span class="dot"></span><div><b>Controller online</b><small>${esc(shorten(appState.system?.hostname||'Local host',22))}</small></div></div><div style="font-size:10px;color:var(--muted)">BIOCOMPUTE v0.2.0 <span style="float:right">MVP</span></div></div></aside><div class="main"><header class="topbar"><div class="crumb">Workspace &nbsp;/&nbsp; <strong>${esc(current?.[2]||'Overview')}</strong></div><div class="top-actions">${badge('LOCAL CONTROLLER','success')}<button data-action="refresh" title="Refresh live data" class="icon-button">${icon('refresh')}</button><button data-action="theme" title="Toggle theme" class="icon-button">${icon(appState.theme==='dark'?'sun':'moon')}</button><div class="avatar">BC</div></div></header><main class="page">${renderPage()}</main></div></div>${appState.wizard?renderWizard():''}${appState.picker?renderPicker():''}${appState.modal?renderModal():''}${appState.runDetail?renderRunDetail():''}<div class="toast-stack" id="toasts"></div>`}
function pageHeading(kicker,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1 class="page-title">${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div><div class="heading-actions">${actions}</div></div>`}
function render(){if(!appState.token){$('#app').innerHTML=renderLogin();bindAuth();return}if(!appState.initialized){$('#app').innerHTML='<div class="splash"><div class="splash-orbit"></div><h2>BioCompute</h2><p>Connecting to your controller...</p></div>';return}$('#app').innerHTML=renderShell();renderToasts();if(appState.route==='studio')queueMicrotask(()=>{studioDragHandlers();drawStudioEdges()})}
function renderLogin(){return `<div class="auth-wrap"><div class="auth-card"><div class="auth-logo">${icon('network',28)}</div><div class="eyebrow">PRIVATE SCIENTIFIC WORKSPACE</div><h1>Welcome to BioCompute</h1><p>Connect securely to your cluster controller. An administrator access token is generated during the first startup.</p><form id="login-form"><div class="field"><label for="access">Controller access token</label><input type="password" id="access" autocomplete="current-password" required placeholder="Paste your access token" /></div><button class="btn primary full" type="submit" style="margin-top:20px">${icon('arrow')} Connect to workspace</button></form><div class="footer-note">Find your token on the controller with <code>cat state/admin-token.txt</code>. The token is stored only in this browser tab's session storage. For remote access, use HTTPS or an authenticated private network.</div></div></div>`}
function bindAuth(){$('#login-form')?.addEventListener('submit',async ev=>{ev.preventDefault();const token=$('#access').value.trim();try {const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})});if(!r.ok)throw Error('Invalid controller access token');appState.token=token;sessionStorage.setItem('bio-token',token);await loadAll();render()}catch(err){notify(err.message,true);alert(err.message)}})}
function renderPage(){switch(appState.route){case 'dashboard':return dashboardPage();case 'nodes':return nodesPage();case 'pipelines':return pipelinePage();case 'experiments':return experimentsPage();case 'studio':return studioPage();case 'runs':return runsPage();case 'settings':return settingsPage();default:return dashboardPage()}}
function statCard(label,value,note,ico,glow=''){return `<div class="card stat-card" style="--glow:${glow||'#53b3ef28'}"><div class="stat-label">${esc(label)}<span class="stat-icon">${icon(ico,18)}</span></div><div class="stat-num">${esc(value)}</div><div class="stat-note">${esc(note)}</div></div>`}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 300 260" fill="none"><defs><radialGradient id="halo"><stop offset="0%" stop-color="#3ca7e6" stop-opacity=".22"/><stop offset="100%" stop-color="#3ca7e6" stop-opacity="0"/></radialGradient></defs><circle cx="155" cy="125" r="125" fill="url(#halo)"/><circle cx="155" cy="125" r="90" stroke="#69bffd" opacity=".22" stroke-dasharray="3 7"/><circle cx="155" cy="125" r="65" stroke="#67ddfa" opacity=".24"/><circle cx="155" cy="125" r="38" fill="#163e5c" stroke="#81d8ff" opacity=".9"/><path d="M142 114h26v22h-26zM147 119h16v12h-16z" stroke="#b7ecff" stroke-width="2"/><g stroke="#4fb9f5" stroke-width="1.3" opacity=".66"><path d="M155 87V38M117 125H55M193 125h50M155 163v45M128 98l-39-39M182 98l36-36M128 152l-42 41M182 152l35 36"/></g>${[[155,35],[48,125],[249,125],[155,212],[86,57],[219,61],[85,196],[221,191]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${i%3===0?10:7}" fill="${i%3===0?'#77ddeb':'#a68dff'}" opacity=".85"/><circle cx="${x}" cy="${y}" r="${i%3===0?18:14}" stroke="#7abefa" opacity=".22"/>`).join('')}</svg>`}
function chart(){const series=appState.cpuHistory.length>0?appState.cpuHistory:[0,0];const vals=series.map((v,i)=>[30+i*(620/Math.max(1,series.length-1)),170-v*1.35]);const points=vals.map(([x,y])=>`${x},${y}`).join(' ');const fill=`${vals[0][0]},170 ${points} ${vals.at(-1)[0]},170`;return `<svg viewBox="0 0 680 204" class="area-chart" preserveAspectRatio="none"><defs><linearGradient id="cpu-gradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5bcafa" stop-opacity=".32"/><stop offset="1" stop-color="#5bcafa" stop-opacity="0"/></linearGradient></defs><g class="axis-grid">${[35,80,125,170].map(y=>`<line x1="30" y1="${y}" x2="650" y2="${y}"/>`).join('')}</g><g class="axis-text"><text x="0" y="39">100%</text><text x="8" y="84">66%</text><text x="8" y="129">33%</text><text x="16" y="174">0%</text></g><polygon points="${fill}" fill="url(#cpu-gradient)"/><polyline points="${points}" fill="none" stroke="#62c8f5" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${vals.at(-1)[0]}" cy="${vals.at(-1)[1]}" r="5" fill="#7fdef7" stroke="#13283f" stroke-width="3"/></svg>`}
function topology(nodes=appState.nodes){const others=nodes.filter(n=>n.id!=='local-controller').slice(0,8);const count=Math.max(others.length,3);const cx=310,cy=154;const local=nodes.find(n=>n.id==='local-controller');let center=`<circle cx="${cx}" cy="${cy}" r="41" fill="#153d5c" stroke="#63cfff" stroke-width="2"/><circle cx="${cx}" cy="${cy}" r="27" fill="#3879a022"/><text x="${cx}" y="${cy+3}" text-anchor="middle" fill="#98e2ff" font-size="14" font-weight="750">${local?.cpu_total||'?'} CPU</text><text x="${cx}" y="${cy+67}" text-anchor="middle">Controller</text>`;const spokes=others.map((n,i)=>{const a=Math.PI*2*i/count-Math.PI/2,x=cx+210*Math.cos(a),y=cy+112*Math.sin(a);return `<path d="M${cx} ${cy} Q${(cx+x)/2+15} ${(cy+y)/2-12} ${x} ${y}" stroke="#529bc8" stroke-dasharray="4 6" opacity=".65" fill="none"/><circle cx="${x}" cy="${y}" r="26" fill="#1d2e47" stroke="${n.authorized?'#57d6a4':'#9c91eb'}" stroke-width="1.6"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="9" fill="#eaf5ff">${esc(n.cpu_total?n.cpu_total+' CPU':'?')}</text><text x="${x}" y="${y+45}" text-anchor="middle" font-size="10">${esc(shorten(n.hostname,13))}</text>`}).join('');return `<svg viewBox="0 0 620 310" class="topology-svg" preserveAspectRatio="xMidYMid meet">${spokes}${center}</svg>`}
function dashboardPage(){const d=appState.data||{};const ns=d.nodes||{},js=d.jobs||{},cpu=d.controller?.details?.cpu_percent??0;const ram=d.controller?.ram_total||0;const used=d.controller?.details?.ram_used||0;return `${pageHeading('CLUSTER COMMAND CENTER','Your science, accelerated.','Control your compute, experiments and workflows from one intelligent workspace.',button('discover',`${icon('refresh',15)} Discover nodes`,'ghost')+button('new-run',`${icon('plus',15)} New analysis`,'primary'))}<div class="hero"><div class="hero-copy"><div class="eyebrow" style="color:#78e1ef">BIOCOMPUTE / COMMAND CENTER</div><h2>Your next discovery<br/>starts here.</h2><p>Run reproducible scientific workflows with direct access to your datasets and live execution monitoring.</p><div class="hero-actions">${button('new-run',`${icon('play',15)} Launch pipeline`,'primary')}${button('navigate',`Explore pipelines ${icon('arrow',14)}`,'ghost','data-route="pipelines"')}</div></div>${heroArt()}</div><div class="grid cols-4">${statCard('Known compute nodes',ns.discovered||0,`${ns.authorized||0} authorized · ${ns.active||0} executing`,'network')}${statCard('Controller CPU',`${Math.round(cpu)}%`,'Live local utilization','cpu','#a388ff29')}${statCard('Pipelines',d.pipelines||0,'Ready to configure','pipeline','#49d6be26')}${statCard('Workflow runs',Object.values(js).reduce((a,b)=>a+b,0),`${js.running||0} running · ${js.completed||0} completed`,'activity','#f9bb6d22')}</div><div class="dashboard-two"><div class="card"><div class="card-title"><h3>Controller CPU usage</h3><div class="legend"><span><i></i> CPU load</span>${badge('LIVE','success')}</div></div><div class="chart-wrap">${chart()}</div><div class="mini-help">Recent browser-sampled values from the controller. Historical monitoring begins after opening BioCompute.</div></div><div class="card"><div class="card-title"><h3>Compute resources</h3>${button('navigate',`Manage ${icon('arrow',13)}`,'ghost sm','data-route="nodes"')}</div><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:9px"><span class="mini-help">Controller RAM</span><strong style="font-size:12px">${bytes(used)} / ${bytes(ram)}</strong></div><div class="progress"><span style="width:${ram?Math.round(used/ram*100):0}%"></span></div><div class="separator"></div>${(appState.nodes||[]).slice(0,4).map(n=>`<div class="node-mini"><div class="mini-icon">${icon(n.id==='local-controller'?'server':'laptop',18)}</div><div class="mini-main"><b>${esc(n.hostname)}</b><small>${esc(n.source)} · ${n.cpu_total?`${n.cpu_total} logical CPU`:'Hardware unknown'}</small></div><span class="dot ${n.id==='local-controller'?'':'warn'}"></span></div>`).join('')}</div></div><div class="dashboard-split"><div class="card"><div class="card-title"><h3>Recent analyses</h3>${button('navigate',`View all ${icon('arrow',13)}`,'ghost sm','data-route="runs"')}</div>${!d.recent_runs?.length?empty('flask','No analyses yet','Start with the FASTQ Quality Explorer to generate real results from the provided example files.',button('new-run','Create first run','primary sm')):d.recent_runs.slice(0,5).map(r=>`<div class="run-row" data-action="run-detail" data-id="${esc(r.id)}"><div style="display:flex;gap:12px;align-items:center"><span class="mini-icon">${icon('flask',18)}</span><div><b>${esc(r.name)}</b><small>${esc(r.pipeline_id)} · ${date(r.created_at)}</small></div></div>${statusBadge(r.status)}</div>`).join('')}</div><div class="card"><div class="card-title"><h3>Execution readiness</h3>${icon('activity',17)}</div>${[['Controller','Online',true],['Built-in QC engine','Available',true],['Nextflow',appState.system?.nextflow?'Installed':'Not installed',appState.system?.nextflow],['HTCondor',appState.system?.htcondor?'Detected':'Not detected',appState.system?.htcondor],['Remote scheduling','Future milestone',false]].map(([a,b,ok])=>`<div style="display:flex;justify-content:space-between;gap:10px;padding:11px 0;border-bottom:1px solid var(--line)"><span style="font-size:12px">${a}</span><span style="font-size:11px;color:var(--${ok?'green':'muted'})">${b}</span></div>`).join('')}<p class="mini-help" style="margin-top:15px">Execution currently runs on this controller. Discovered remote machines are inventory candidates, not active workers.</p></div></div>`}
function pipelinePage(){const query=appState.search.toLowerCase();const list=appState.pipelines.filter(p=>!query||(`${p.name} ${p.description} ${p.engine} ${p.category}`).toLowerCase().includes(query));return `${pageHeading('WORKFLOW CATALOG','Pipeline Library','Import, configure and launch reproducible scientific workflows.',button('registry-toggle',`${icon('search',15)} Nextflow Registry`,'ghost')+button('import-pipeline',`${icon('upload',15)} Import local project`,'ghost')+button('new-run',`${icon('plus',15)} New analysis`,'primary'))}${appState.registryOpen?registryCatalogPage():''}<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:22px;gap:12px;flex-wrap:wrap"><div class="searchbar">${icon('search',16)}<input placeholder="Search pipelines, methods, engines..." id="pipeline-search" value="${attr(appState.search)}" /></div><div class="mini-help">${list.length} pipeline${list.length===1?'':'s'} · bundled + imported</div></div><div class="grid cols-3">${list.map(p=>`<div class="card pipeline-card hoverable"><div class="pipe-visual"><div class="pipe-icon">${icon(p.engine==='nextflow'?'pipeline':'flask',25)}</div>${badge(p.engine==='nextflow'?'NEXTFLOW DSL2':'LOCAL PYTHON',p.engine==='nextflow'?'info':'success')}</div><div class="pipe-card-title">${esc(p.name)}</div><div class="pipe-desc">${esc(p.description)}</div><div class="pipe-footer"><span class="mini-help">${esc(p.category)} · ${p.fields?.length||0} parameters</span>${button('open-pipeline',`Configure ${icon('arrow',13)}`,'primary sm',`data-id="${attr(p.id)}"`)}</div></div>`).join('')}${!list.length?empty('search','No pipelines match','Try another search or import a Nextflow project.'):''}</div><div class="notice" style="margin-top:24px">${icon('info',15)} &nbsp; To import a local Nextflow project, add its directory under an approved <code>BIOCOMPUTE_PIPELINE_ROOTS</code> path. Online registry imports download public Git repositories; imported workflow code must be reviewed before execution.</div>`}
function experimentsPage(){return `${pageHeading('SAMPLE MANAGEMENT','Experiments','Organize your datasets, conditions, replicates and experimental design.',button('edit-experiment',`${icon('plus',15)} New experiment`,'primary'))}${!appState.experiments.length?`<div class="card">${empty('flask','Your experiment library is empty','Create a sample manifest or load the included FASTQ example data to prepare your first analysis.',button('edit-experiment','Create experiment','primary'))}</div>`:`<div class="grid cols-3">${appState.experiments.map(x=>`<div class="card hoverable" style="display:flex;flex-direction:column;gap:14px"><div class="pipe-visual" style="height:38px"><div class="pipe-icon" style="height:38px;width:38px">${icon('flask',19)}</div>${badge(esc(x.assay||'Generic'))}</div><h3 style="font-size:16px;margin:2px 0;font-weight:780">${esc(x.name)}</h3><div class="mini-help">${x.sample_count} samples · Updated ${date(x.updated_at)}</div><div class="progress"><span style="width:${Math.min(100,Math.max(8,x.sample_count*9))}%"></span></div><div style="display:flex;gap:9px;margin-top:auto">${button('edit-experiment',`${icon('sliders',14)} Edit samples`,'sm',`data-id="${x.id}"`)}${button('experiment-run',`${icon('play',14)} Run`,'primary sm',`data-id="${x.id}"`)}</div></div>`).join('')}</div>`}<div class="card" style="margin-top:22px"><div class="card-title"><h3>Experimental metadata</h3>${badge('PIPELINE-AWARE')}</div><p class="subtitle">The same experiment table stores sample IDs, treatments, replicate numbers and input locations. When you launch a pipeline, BioCompute validates and adapts this manifest to its expected samplesheet.</p></div>`}
function nodesPage(){const ns=appState.nodes;return `${pageHeading('COMPUTE FABRIC','Compute Nodes','Discover candidates, inspect available hardware, and configure controller allocations.',button('manual-node',`${icon('plus',15)} Add hostname`,'ghost')+button('discover',`${icon('refresh',15)} Refresh discovery`,'primary'))}<div class="grid cols-4" style="margin-bottom:18px">${statCard('Discovered',ns.length,'Local, Tailscale, scheduler','network')}${statCard('Authorized',ns.filter(n=>n.authorized).length,'Explicitly approved','check')}${statCard('Executing now',ns.filter(n=>n.can_execute_now).length,'Controller-only milestone','cpu')}${statCard('Known logical CPU',ns.reduce((a,n)=>a+n.cpu_total,0),'Across inventoried devices','bolt')}</div><div class="card" style="margin-bottom:19px"><div class="card-title"><h3>Compute fabric topology</h3>${badge('PASSIVE DISCOVERY','info')}</div><div class="node-topology">${topology(ns)}</div><div class="mini-help" style="margin-top:14px">Devices on Tailscale or in HTCondor may appear as candidates. Their hardware, authorization, and execution readiness are not assumed. Broad LAN scanning is intentionally disabled until a trusted site agent and scoped authorization are configured.</div></div><div class="grid cols-3">${ns.map(n=>nodeCard(n)).join('')}</div>${ns.length===1?`<div class="notice" style="margin-top:22px">${icon('info',16)} &nbsp; Only this controller was detected. Run a discovery refresh after configuring Tailscale or HTCondor on this host. The home-network discovery agent and worker enrollment are planned, not yet operational.</div>`:''}`}
function nodeCard(n){const ready=n.can_execute_now,local=n.id==='local-controller';return `<div class="card node-card"><div class="node-heading"><div class="node-icon">${icon(local?'server':'laptop',23)}</div>${statusBadge(ready?'online':n.status==='discovered'?'discovered':'offline')}</div><div><div class="node-name">${esc(n.hostname)}</div><div class="node-spec">${esc(n.os)} · ${esc(n.arch)} · ${esc(n.source)}</div></div><div class="grid cols-2" style="gap:8px"><div class="detail-stat"><small>Logical CPU</small><div class="node-big">${n.cpu_total||'—'}</div></div><div class="detail-stat"><small>Memory</small><div class="node-big" style="font-size:17px">${bytes(n.ram_total)}</div></div></div><div class="node-alloc"><label><span>Advertised CPU limit</span><strong>${n.cpu_limit||0}${n.cpu_total?` / ${n.cpu_total}`:''}</strong></label><input type="range" min="1" max="${n.cpu_total||1}" value="${n.cpu_limit||1}" data-node="${attr(n.id)}" data-node-field="cpu_limit" ${!local?'disabled':''}/></div><div class="node-footer"><span class="mini-help" style="max-width:200px">${local?'Policy saved; no OS-level CPU enforcement in this release.':'Candidate only. Remote enrollment and execution unavailable.'}</span><label title="Idle-only policy"><input class="toggle" type="checkbox" data-node="${attr(n.id)}" data-node-field="idle_only" ${n.idle_only?'checked':''} ${!local?'disabled':''}/></label></div></div>`}
function runsPage(){return `${pageHeading('EXECUTION CENTER','Run Manager','Monitor real analyses, review logs and download generated results.',button('new-run',`${icon('play',15)} New analysis`,'primary'))}<div class="grid cols-4" style="margin-bottom:20px">${statCard('All runs',appState.runs.length,'Persisted execution history','jobs')}${statCard('Running',appState.runs.filter(x=>x.status==='running').length,'Currently processing','activity')}${statCard('Completed',appState.runs.filter(x=>x.status==='completed').length,'Artifacts available','check')}${statCard('Failed / interrupted',appState.runs.filter(x=>['failed','interrupted'].includes(x.status)).length,'Require investigation','alert')}</div><div class="card" style="padding:0"><div style="padding:21px 23px 15px;display:flex;align-items:center;justify-content:space-between"><strong>Execution history</strong>${badge(`${appState.runs.length} RUNS`)}</div>${!appState.runs.length?empty('jobs','Nothing in the queue','Launch the bundled QC example to verify end-to-end execution.',button('new-run','Start analysis','primary')):appState.runs.map(r=>`<div class="run-row" data-action="run-detail" data-id="${esc(r.id)}"><div style="display:flex;align-items:center;gap:13px;min-width:0"><span class="mini-icon">${icon(r.status==='completed'?'check':r.status==='failed'?'alert':'terminal',18)}</span><div style="min-width:0"><b>${esc(r.name)}</b><small>${esc(r.pipeline_id)} · ${r.samples.length} samples · ${date(r.created_at)}</small></div></div><div style="display:flex;gap:14px;align-items:center">${statusBadge(r.status)}${icon('arrow',15)}</div></div>`).join('')}</div>`}
function settingsPage(){const s=appState.system||{};return `${pageHeading('SYSTEM CONFIGURATION','Settings','Controller configuration, integrations, data roots, and security boundaries.',button('logout',`${icon('logout',15)} Sign out`,'ghost'))}<div class="grid cols-2"><div class="card"><div class="card-title"><h3>Controller environment</h3>${badge('RUNNING','success')}</div>${[['Hostname',s.hostname],['BioCompute',`v${s.version}`],['Execution scope','Local controller only'],['Nextflow',s.nextflow?'Installed':'Not found'],['HTCondor',s.htcondor?'Detected':'Not found'],['Tailscale',s.tailscale?'Detected':'Not found']].map(([k,v])=>`<div style="display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--line)"><span class="mini-help">${esc(k)}</span><strong style="font-size:11px">${esc(v||'—')}</strong></div>`).join('')}</div><div class="card"><div class="card-title"><h3>Approved data directories</h3>${icon('folder',20)}</div>${(s.data_roots||[]).map(p=>`<div class="notice" style="margin-bottom:10px;overflow-wrap:anywhere">${icon('folder',14)} &nbsp; <code>${esc(p)}</code></div>`).join('')}<p class="mini-help">Set <code>BIOCOMPUTE_DATA_ROOTS</code> on the controller to enable additional datasets. File browser access is restricted to these roots. Restart to apply environment changes.</p></div><div class="card"><div class="card-title"><h3>Security model</h3>${icon('settings',20)}</div><p class="subtitle">This first milestone is designed for a single trusted administrator. Every API resource requires the controller access token; downloaded artifacts are authenticated. Keep the service on loopback or expose it only through a protected TLS endpoint.</p><div class="notice warn" style="margin-top:17px">BioCompute runs scientific workflow code with the execution service's operating-system privileges. Do not expose it directly to the internet or import untrusted Nextflow projects.</div></div><div class="card"><div class="card-title"><h3>Roadmap and limitations</h3>${icon('spark',20)}</div>${[['Working','FASTQ analysis, local Nextflow adapter, logs, experiments'],['Working','Passive discovery and candidate inventory'],['Draft editor','Visual graph creation and persistence'],['Planned','Remote worker enrollment and scheduler execution'],['Planned','Visual graph to executable DSL2 compiler'],['Planned','PostgreSQL migrations / multi-user permissions']].map(([k,v])=>`<div style="display:flex;gap:12px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--line)">${badge(k,k==='Working'?'success':'warning')}<span style="font-size:12px;line-height:1.55">${esc(v)}</span></div>`).join('')}</div></div>`}
function newWizard(pipelineId=null,experimentId=null){const p=appState.pipelines.find(x=>x.id===pipelineId)||appState.pipelines[0];const exp=appState.experiments.find(x=>x.id===Number(experimentId));appState.wizard={mode:'run',step:0,pipelineId:p?.id||'',name:`${p?.name||'Analysis'} · ${new Date().toLocaleDateString()}`,samples:exp?structuredClone(exp.samples):[],experimentId:exp?.id||null,params:Object.fromEntries((p?.fields||[]).filter(f=>f.default!==undefined).map(f=>[f.name,f.default])),validation:null};render()}
function newExperiment(id=null){const ex=appState.experiments.find(x=>x.id===Number(id));appState.wizard={mode:'experiment',step:1,pipelineId:appState.pipelines[0]?.id||'',name:ex?.name||'New experiment',assay:ex?.assay||'Genomics',samples:ex?structuredClone(ex.samples):[],experimentId:ex?.id||null,params:{},validation:null};render()}
function selectedPipeline(){return appState.pipelines.find(p=>p.id===appState.wizard?.pipelineId)||appState.pipelines[0]}
function renderWizard(){const w=appState.wizard;const p=selectedPipeline();let content='';if(w.mode==='experiment'){content=`<div class="section"><div class="field"><label>Experiment name</label><input data-w-field="name" value="${attr(w.name)}" /></div><div class="field" style="margin-top:15px"><label>Assay category</label><select data-w-field="assay">${['Genomics','Transcriptomics','Epigenomics','Proteomics','Other'].map(x=>`<option ${w.assay===x?'selected':''}>${x}</option>`).join('')}</select></div></div>${sampleEditor()}`}else if(w.step===0){content=`<div class="section"><div class="field"><label>Analysis name</label><input data-w-field="name" value="${attr(w.name)}"/></div></div><div class="section"><div class="section-title">Choose a pipeline</div><div style="display:grid;gap:10px">${appState.pipelines.map(x=>`<button style="text-align:left;width:100%;border:1px solid ${x.id===w.pipelineId?'var(--blue)':'var(--line)'};background:var(--surface2);color:var(--text);border-radius:11px;padding:16px;display:flex;align-items:center;gap:13px" data-action="select-w-pipeline" data-id="${attr(x.id)}"><span class="mini-icon">${icon(x.engine==='builtin'?'flask':'pipeline',20)}</span><span style="flex:1"><b style="display:block;font-size:13px">${esc(x.path)}</b><small style="font-size:11px;color:var(--muted)">${esc(x.engine)} · ${esc(x.category)}</small></span>${x.id===w.pipelineId?icon('check',18):icon('arrow',16)}</button>`).join('')}</div></div><div class="notice">The built-in FASTQ Quality Explorer is available immediately. Nextflow pipelines require Nextflow installed on the controller.</div>`}else if(w.step===1){content=`<div class="section"><div class="section-title">Existing experiment <span class="mini-help">optional</span></div><select class="form-control" id="w-select-experiment"><option value="">Create a new sample table</option>${appState.experiments.map(x=>`<option value="${x.id}" ${x.id===w.experimentId?'selected':''}>${esc(x.name)} (${x.sample_count} samples)</option>`).join('')}</select></div>${sampleEditor()}`}else if(w.step===2){content=parametersStep(p)}else if(w.step===3){content=resourcesStep()}else {content=reviewStep(p)}const title=w.mode==='experiment'?'Experiment designer':'Launch analysis';const heading=w.mode==='experiment'?'Create, annotate and save samples':`New run · ${p?.name||'Pipeline'}`;const steps=['Pipeline','Samples','Parameters','Resources','Review'];return `<div class="drawer-overlay" data-action="close-drawer-overlay"><div class="drawer"><div class="drawer-head"><div><div class="eyebrow">${esc(title.toUpperCase())}</div><h2>${esc(heading)}</h2></div><button class="icon-button" data-action="close-wizard" title="Close">${icon('close',18)}</button></div><div class="drawer-body">${w.mode==='experiment'?'':`<div class="pill-steps">${steps.map((s,i)=>`<span class="step-pill ${i===w.step?'active':i<w.step?'done':''}">${i+1}. ${s}</span>`).join('')}</div>`}${content}</div><div class="drawer-footer"><div>${w.mode==='experiment'?'':w.step>0?button('wizard-prev',`${icon('arrow',14)} Back`,'ghost'):button('close-wizard','Cancel','ghost')}</div><div style="display:flex;gap:8px">${w.mode==='experiment'?button('save-experiment',`${icon('check',15)} Save experiment`,'primary'):w.step<4?button('wizard-next',`Continue ${icon('arrow',15)}`,'primary'):button('launch-run',`${icon('play',15)} Launch analysis`,'primary')}</div></div></div></div>`}
function sampleEditor(){const samples=appState.wizard.samples;return `<div class="section"><div class="section-title"><span>Sample manifest <span class="condition-chip">${samples.length} rows</span></span><div style="display:flex;gap:8px">${button('add-demo',`${icon('spark',13)} Example data`,'sm')}${button('add-sample',`${icon('plus',13)} Add row`,'sm')}</div></div><p class="mini-help" style="margin:-5px 0 14px">Edit names, conditions, replicates, batches and input files. Browse files within authorized data roots. CSV import accepts sample, condition, replicate, file1 and file2.</p>${samples.length?`<div class="table-wrap"><table class="wizard-table"><thead><tr><th>Sample ID</th><th>Condition</th><th>Rep</th><th>Batch</th><th>R1 / File</th><th>R2</th>${(appState.wizard.mode==='run'?selectedPipeline()?.sample_columns||[]:[]).filter(c=>!['sample','sample_id','fastq_1','fastq_2','r1','r2','condition','replicate','batch'].includes(c.name)).map(c=>`<th title="${attr(c.description||'')}">${esc(c.name)}${c.required?' *':''}</th>`).join('')}<th></th></tr></thead><tbody>${samples.map((s,i)=>`<tr>${[['sample',125],['condition',115],['replicate',55],['batch',70]].map(([field,width])=>`<td><input style="width:${width}px" data-sample="${i}" data-field="${field}" type="${field==='replicate'?'number':'text'}" min="1" value="${attr(s[field]||'')}"/></td>`).join('')}${['file1','file2'].map(field=>`<td><div class="file-select"><input class="file-field file-path" data-sample="${i}" data-field="${field}" value="${attr(s[field]||'')}" title="${attr(s[field]||'')}" placeholder="Choose file"/><button data-action="pick-file" data-row="${i}" data-field="${field}" title="Browse data folders">${icon('folder',14)}</button></div></td>`).join('')}${(appState.wizard.mode==='run'?selectedPipeline()?.sample_columns||[]:[]).filter(c=>!['sample','sample_id','fastq_1','fastq_2','r1','r2','condition','replicate','batch'].includes(c.name)).map(c=>`<td><input style="width:125px" data-sample="${i}" data-field="metadata.${attr(c.name)}" value="${attr(s.metadata?.[c.name]||'')}" placeholder="${attr(c.name)}"/></td>`).join('')}<td><button data-action="remove-sample" data-row="${i}" title="Remove sample">${icon('close',13)}</button></td></tr>`).join('')}</tbody></table></div>`:empty('database','No samples yet','Add rows manually, load the bundled example, or import a CSV manifest.') }<div style="display:flex;justify-content:space-between;gap:9px;align-items:center;flex-wrap:wrap;margin-top:14px"><label class="btn sm" style="cursor:pointer">${icon('upload',13)} Import CSV <input type="file" id="csv-import" accept=".csv,.tsv,text/csv,text/tab-separated-values" style="display:none"/></label>${button('validate-samples',`${icon('check',14)} Validate samples`,'ghost sm')}</div>${appState.wizard.validation?`<div class="notice ${appState.wizard.validation.valid?'success':'danger'}" style="margin-top:12px">${appState.wizard.validation.valid?'Sample paths and names validated.':appState.wizard.validation.errors.map(esc).join('<br>')}${appState.wizard.validation.warnings?.length?'<br>'+appState.wizard.validation.warnings.map(esc).join('<br>'):''}</div>`:''}</div>`}
function parametersStep(p){let groups={};for(const f of (p.fields||[])){(groups[f.group||'General']??=[]).push(f)}return `<div class="section"><div class="section-title">${esc(p.name)} · Parameters</div><p class="mini-help">Generated from this pipeline's declared JSON schema. Edit individual values, save a preset, or restore defaults.</p></div><div style="display:flex;gap:8px;margin-bottom:20px">${button('restore-params',`${icon('refresh',13)} Restore defaults`,'sm')}${button('save-preset',`${icon('copy',13)} Save preset`,'sm')}</div>${Object.entries(groups).map(([g,fields])=>`<div class="config-group"><h4>${esc(g)}</h4><div class="form-grid">${fields.map(f=>parameterField(f)).join('')}</div></div>`).join('')||'<div class="notice">No schema-defined parameters. This pipeline may need command-line flags documented by its author.</div>'}${(appState.wizard.params?.__extra||null)?'':''}`}
function parameterField(f){const w=appState.wizard;const value=w.params[f.name]??f.default??'';const managed=['input','outdir'].includes(f.name)&&selectedPipeline().engine==='nextflow';let control='';if(managed) control=`<input value="Managed automatically for each execution" disabled/>`;else if(f.enum?.length)control=`<select data-param="${attr(f.name)}">${f.enum.map(v=>`<option value="${attr(v)}" ${String(value)===String(v)?'selected':''}>${esc(v)}</option>`).join('')}</select>`;else if(f.type==='boolean')control=`<label style="display:flex;align-items:center;gap:9px;color:var(--muted);font-size:12px"><input type="checkbox" style="width:17px;min-height:17px;accent-color:#58b8e8" data-param="${attr(f.name)}" ${value?'checked':''}/> ${value?'Enabled':'Toggle option'}</label>`;else control=`<input data-param="${attr(f.name)}" type="${['integer','number'].includes(f.type)?'number':'text'}" ${f.type==='integer'?'step="1"':f.type==='number'?'step="any"':''} ${f.minimum!==undefined?`min="${f.minimum}"`:''} ${f.maximum!==undefined?`max="${f.maximum}"`:''} value="${attr(value)}" placeholder="${esc(f.default??'Enter value')}"/>`;return `<div class="field ${f.description?.length>85?'full-span':''}"><label>${esc(f.title||f.name)} ${f.required?'<span class="param-required">*</span>':''}</label>${control}<small>${esc(f.description||f.name)}</small></div>`}
function resourcesStep(){return `<div class="section"><div class="section-title">Execution target</div><p class="mini-help">Resource requests are separate from pipeline scientific parameters.</p></div>${appState.nodes.map(n=>`<div style="border:1px solid var(--line);background:var(--surface2);border-radius:12px;padding:17px;margin-bottom:12px;display:flex;align-items:center;gap:13px"><div class="mini-icon">${icon(n.id==='local-controller'?'server':'laptop',18)}</div><div style="flex:1"><b>${esc(n.hostname)}</b><small style="display:block;color:var(--muted);margin-top:5px;font-size:11px">${n.cpu_total||'?'} logical CPU · ${bytes(n.ram_total)} · ${esc(n.source)}</small></div>${n.can_execute_now?badge('SELECTED','success'):badge('NOT YET EXECUTABLE','warning')}</div>`).join('')}<div class="notice">Only the local controller is an actual execution target in this milestone. Candidate machines can be inventoried but cannot yet run tasks. No remote data transfer occurs.</div><div class="section"><div class="section-title">Execution policy</div><div class="detail-stat"><small>Controller slot limit</small><b>${appState.nodes.find(n=>n.id==='local-controller')?.cpu_limit||'Detected at startup'} logical cores (policy only)</b></div><p class="mini-help">The current runner launches one local process per run. Resource sliders do not yet enforce CPU pinning, RAM cgroups or scheduler-level isolation.</p></div>`}
function reviewStep(p){const w=appState.wizard;return `<div class="section"><div class="section-title">Review your analysis</div><p class="mini-help">Confirm your pipeline, input files and parameters before running real code on this controller.</p></div><div class="grid cols-2"><div class="detail-stat"><small>Pipeline</small><b>${esc(p.name)}</b></div><div class="detail-stat"><small>Engine</small><b>${esc(p.engine)}</b></div><div class="detail-stat"><small>Samples</small><b>${w.samples.length}</b></div><div class="detail-stat"><small>Execution</small><b>Local controller</b></div></div><div class="section"><div class="section-title">Configuration snapshot</div><div class="code-panel">${esc(JSON.stringify({name:w.name,pipeline:p.id,engine:p.engine,params:w.params,samples:w.samples,execution:['local-controller']},null,2))}</div></div><div class="notice ${p.engine==='nextflow'&&!appState.system.nextflow?'warn':'success'}">${p.engine==='nextflow'&&!appState.system.nextflow?'Nextflow is not installed. This run will not launch until the runtime is installed.':'The run will execute on the local controller and save all generated outputs under its run directory.'}</div>`}
function renderRunDetail(){const r=appState.runDetail;if(!r)return '';return `<div class="drawer-overlay" data-action="close-run-overlay"><div class="drawer"><div class="drawer-head"><div><div class="eyebrow">EXECUTION DETAILS</div><h2>${esc(shorten(r.name,52))}</h2></div><button class="icon-button" data-action="close-run">${icon('close',18)}</button></div><div class="drawer-body"><div class="section"><div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px">${statusBadge(r.status)}<small class="mini-help">${esc(r.id)}</small></div><div class="run-detail-meta"><div class="detail-stat"><small>Pipeline</small><b>${esc(r.pipeline_id)}</b></div><div class="detail-stat"><small>Samples</small><b>${r.samples?.length||0}</b></div><div class="detail-stat"><small>Submitted</small><b>${date(r.created_at)}</b></div><div class="detail-stat"><small>Finished</small><b>${date(r.finished_at)}</b></div></div>${r.error?`<div class="notice danger" style="margin-top:14px">${esc(r.error)}</div>`:''}</div><div class="section"><div class="section-title">Execution log ${statusBadge(r.status)}</div><div class="code-panel" id="run-log" style="min-height:200px;max-height:410px">${esc(appState.runLog||'Waiting for log output...')}</div><p class="mini-help">Live output is streamed to the controller's persisted run.log file.</p></div><div class="section"><div class="section-title">Artifacts and results <span class="condition-chip">${appState.artifacts.length} files</span></div>${appState.artifacts.length?appState.artifacts.map(x=>`<div class="artifact-row"><div style="display:flex;align-items:center;gap:10px"><span class="mini-icon">${icon(x.path.endsWith('.html')?'chart':'file',16)}</span><div><b style="font-size:12px">${esc(x.path)}</b><small style="display:block;color:var(--muted)">${bytes(x.bytes)}</small></div></div>${button('download-artifact',icon('download',15),'sm',`data-name="${attr(x.path)}"`)}</div>`).join(''):empty('folder','No artifacts yet','Output files will appear here as soon as they are written.')}</div></div><div class="drawer-footer">${button('view-studio-execution',`${icon('studio',14)} View execution graph & outputs`,'ghost')}${button('close-run','Close','ghost')}${['queued','running'].includes(r.status)?button('cancel-run',`${icon('close',14)} Cancel run`,'danger'):button('new-run',`${icon('plus',14)} Another analysis`,'primary')}</div></div></div>`}
function renderPicker(){const picker=appState.picker;const data=picker.list||{roots:[],entries:[],path:null};return `<div class="file-browse-overlay" data-action="close-picker-overlay"><div class="file-modal"><div class="file-modal-head"><div><div class="eyebrow">APPROVED DATA ROOTS</div><h3 style="margin:6px 0 0">Choose ${picker.field==='file2'?'R2 / secondary file':'R1 / input file'}</h3></div><button class="icon-button" data-action="close-picker">${icon('close',18)}</button></div><div class="file-content"><p class="breadcrumb-path">${esc(data.path||'Choose a dataset root')}</p>${data.parent?`<button class="file-row" data-action="browse-dir" data-path="${attr(data.parent)}">${icon('arrow',16)}<span>.. Parent directory</span></button>`:''}${data.roots?.map(r=>`<button class="file-row" data-action="browse-dir" data-path="${attr(r.path)}">${icon('database',18)}<span>${esc(r.name)}</span><small>Root</small></button>`).join('')||''}${data.entries?.map(x=>`<button class="file-row" data-action="${x.directory?'browse-dir':'select-file'}" data-path="${attr(x.path)}">${icon(x.directory?'folder':'file',17)}<span>${esc(x.name)}</span><small>${x.directory?'Folder':bytes(x.bytes)}</small></button>`).join('')||''}${data.path && !data.entries?.length?empty('folder','This folder is empty','Choose another folder or configure additional approved roots.'):''}</div></div></div>`}
function renderModal(){const m=appState.modal;let content='',title='';if(m.type==='import'){title='Import Nextflow project';content=`<p>Select a local Nextflow project under an approved pipeline root. It must contain <code>main.nf</code>.</p><div class="field"><label>Absolute directory path</label><input id="import-path" value="${attr(m.path||'')}" placeholder="/srv/pipelines/my-pipeline"/></div><div class="field" style="margin-top:15px"><label>Display name (optional)</label><input id="import-name" value="${attr(m.name||'')}" placeholder="My custom pipeline"/></div>`}else if(m.type==='manual'){title='Add candidate machine';content=`<p>Create an inventory entry for a known computer. This does not connect to or install software on the machine.</p><div class="field"><label>Hostname</label><input id="node-host" placeholder="home-imac.local"/></div><div class="field" style="margin-top:14px"><label>Address (optional)</label><input id="node-address" placeholder="192.168.1.50 or Tailscale IP"/></div>`}return `<div class="modal-overlay" data-action="close-modal-overlay"><div class="modal"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:15px"><span class="mini-icon">${icon(m.type==='manual'?'network':'pipeline',21)}</span><button class="icon-button" data-action="close-modal">${icon('close',16)}</button></div><h2>${title}</h2>${content}<div class="modal-footer">${button('close-modal','Cancel','ghost')}${button('modal-submit',`${icon('check',14)} ${m.type==='manual'?'Add candidate':'Import pipeline'}`,'primary')}</div></div></div>`}
const modulePalette=[{id:'input',name:'FASTQ Input',desc:'Samplesheet channel',ico:'folder'},{id:'fastqc',name:'FastQC',desc:'Quality control',ico:'activity'},{id:'trim',name:'Fastp Trim',desc:'Adapter removal',ico:'sliders'},{id:'align',name:'Bowtie2 Align',desc:'Read alignment',ico:'pipeline'},{id:'peaks',name:'MACS3 Peaks',desc:'Peak calling',ico:'chart'},{id:'multiqc',name:'MultiQC',desc:'Aggregated report',ico:'file'},{id:'custom',name:'Custom command',desc:'Custom process',ico:'terminal'}];
function registryCatalogPage(){const data=appState.registry;const q=appState.registryQuery.toLowerCase().trim();const shown=(data?.pipelines||[]).filter(p=>!q||`${p.id} ${p.description} ${p.keywords}`.toLowerCase().includes(q));return `<div class="card registry-browser"><div class="section-title"><span>Nextflow Registry · Public pipeline catalog</span>${button('registry-refresh',`${icon('refresh',14)} Refresh catalog`,'ghost sm')}</div><div class="searchbar" style="max-width:600px">${icon('search',16)}<input id="registry-search" value="${attr(appState.registryQuery)}" placeholder="Search all published pipelines, methods, keywords..."/></div><p class="mini-help" style="margin:12px 0">${data?`${data.total} published pipelines discovered; ${shown.length} matching.`:'Loading online pipeline catalog...'} Importing downloads third-party executable workflow code; review its contents before running.</p><div class="registry-results">${shown.slice(0,300).map(p=>`<div class="registry-row"><div><b>${esc(p.id)}</b> ${badge(p.version||'latest','info')}<p>${esc(shorten(p.description,180))}</p></div>${button('registry-import','Import','primary sm',`data-id="${attr(p.id)}"`)}</div>`).join('')||empty('search','No matching pipelines',data?'Try a broader search.':'The registry could not be loaded.')}</div></div>`}
function studioPage(){return `${studioModeBar()}${appState.studioMode==='execution'?studioExecutionPage():studioDesigner()}`}
function studioModeBar(){return `<div class="studio-mode-bar">${button('studio-design','Workflow designer',appState.studioMode==='design'?'primary':'ghost')}${button('studio-execution','Execution & outputs',appState.studioMode==='execution'?'primary':'ghost')}<small>Draft graphs are not executable; execution view inspects real pipeline runs.</small></div>`}
function studioExecutionPage(){
 const r=appState.runs.find(x=>x.id===appState.executionRunId);
 const e=appState.execution;
 const rows=(e?.published||[]);
 return `${pageHeading('LIVE EXECUTION','Processing stages & generated files','Inspect actual Nextflow task records and published output files from the selected run.',button('studio-execution-refresh',`${icon('refresh',14)} Refresh execution`,'ghost'))}
 <div class="card execution-top"><div class="field" style="flex:1"><label>Analysis run</label><select id="studio-execution-run"><option value="">Select a run to inspect</option>${appState.runs.map(run=>`<option value="${attr(run.id)}" ${run.id===appState.executionRunId?'selected':''}>${esc(shorten(run.name,65))} — ${esc(run.status)}</option>`).join('')}</select></div>${r?statusBadge(r.status):''}</div>
 ${!e?empty('activity','Select a pipeline execution','Start a real pipeline through Pipeline Library, then select its run here to see stages and generated files.'):`
 <div class="grid cols-3" style="margin:15px 0"><div class="card mini-metric"><small>Processing tasks</small><h2>${e.tasks.length}</h2></div><div class="card mini-metric"><small>Published output files</small><h2>${e.published_count}</h2></div><div class="card mini-metric"><small>Execution state</small><h2>${esc(e.status)}</h2></div></div>
 <div class="grid cols-2"><div class="card"><div class="section-title">Live processing stages ${e.partial?badge('updating','info'):''}</div>${e.tasks.length?e.tasks.map((task,i)=>`<div class="exec-task"><div class="exec-task-head"><span class="stage-number">${i+1}</span><b>${esc(task.name)}</b>${statusBadge(task.status.toLowerCase())}</div>${task.duration?`<small>${esc(task.duration)}</small>`:''}${task.workspace_files?.length?`<details><summary>${task.workspace_files.length} observed workspace files</summary><div class="workspace-files">${task.workspace_files.map(f=>`<div title="${attr(f.path)}">${icon('file',13)} ${esc(f.path)} <small>${bytes(f.bytes)}</small></div>`).join('')}</div></details>`:'<small>No workspace file metadata recorded yet.</small>'}</div>`).join(''):empty('activity','No process traces yet',e.engine==='nextflow'?'Nextflow trace records may appear during or after pipeline execution.':'No processing steps recorded.')}</div><div class="card"><div class="section-title">Published outputs ${badge(`${rows.length} files`,'success')}</div>${rows.length?rows.map(f=>`<div class="output-file-row"><div>${icon('file',16)}<span title="${attr(f.path)}">${esc(f.path)}</span><small>${bytes(f.bytes)}</small></div>${button('download-studio-output',icon('download',14),'sm',`data-path="${attr(f.path)}"`)}</div>`).join(''):empty('folder','No published results yet','Files in the run results directory will appear here as they are written.')}</div></div>
 <div class="notice" style="margin-top:16px">${icon('info',15)} &nbsp; ${esc(e.task_file_note)} ${e.truncated?'This view is capped to protect performance.':''}</div>
 ${r?`<div style="margin-top:12px">${button('open-studio-run',`${icon('terminal',15)} Open run logs`,'ghost')}</div>`:''}`}
 `;
}
function studioDesigner(){const g=appState.studio;return `${pageHeading('VISUAL WORKFLOW DESIGNER','Pipeline Studio','Drag modules onto the canvas, arrange processing steps, and save a workflow draft.',button('load-graph',`${icon('folder',15)} Open draft`,'ghost')+button('save-graph',`${icon('check',15)} Save draft`,'primary'))}<div class="notice warn" style="margin-bottom:18px">${icon('alert',15)} &nbsp; Visual authoring is a working <strong>draft editor</strong>. It saves real graph definitions but does not yet export or execute DSL2. Existing Nextflow pipelines are executable through Pipeline Library.</div><div class="studio-toolbar"><div class="searchbar" style="flex:1"><span class="mini-help">Workflow name:</span><input id="studio-name" value="${attr(g.name)}" placeholder="Workflow name" /></div>${button('clear-graph',`${icon('trash',15)} Clear`,'ghost')}${badge(`${g.nodes.length} modules · ${g.edges.length} links`)}</div><div class="studio-layout"><aside class="card palette"><div class="section-title">Module palette</div><div class="mini-help" style="margin:-5px 0 15px">Click or drag a module onto the canvas.</div>${modulePalette.map((m,i)=>`<div class="palette-item" draggable="true" data-module="${m.id}" data-action="add-module">${icon(m.ico,17)}<span>${esc(m.name)}</span></div>`).join('')}</aside><div><div class="studio-board" id="studio-board"><div class="studio-hint">Drag blocks · Click output then input to link · Click block to select</div><svg class="studio-edges" id="studio-edges"></svg>${g.nodes.map(n=>`<div class="studio-node ${g.selected===n.id?'selected':''}" data-studio-node="${n.id}" style="left:${n.x}px;top:${n.y}px"><div class="port in" data-action="connect-target" data-id="${n.id}" title="Connect here"></div><div style="display:flex;align-items:center;gap:9px">${icon(modulePalette.find(m=>m.id===n.type)?.ico||'cpu',16)}<strong>${esc(n.label)}</strong></div><small>${esc(modulePalette.find(m=>m.id===n.type)?.desc||'Custom process')}</small><div class="port out" data-action="connect-source" data-id="${n.id}" title="Connect from here"></div></div>`).join('')}</div><div class="studio-details">${g.connectFrom?'Click the left port of a target node to create a connection.':g.selected?`Selected module <b>${esc(g.nodes.find(n=>n.id===g.selected)?.label||'')}</b>. ${button('remove-studio-node',`${icon('trash',13)} Remove`,'danger sm')}`:`Select a module to inspect it. Connections: ${g.edges.map((edge,i)=>`${esc(g.nodes.find(n=>n.id===edge.from)?.label||edge.from)} → ${esc(g.nodes.find(n=>n.id===edge.to)?.label||edge.to)} ${button('remove-studio-edge','Remove','sm',`data-index=\"${i}\"`)}`).join(' · ')||'None'}.`}</div></div></div>${appState.graphs.length?`<p class="mini-help" style="margin-top:16px">${appState.graphs.length} saved draft${appState.graphs.length!==1?'s':''} available on the controller.</p>`:''}`}
function drawStudioEdges(){const board=$('#studio-board'),svg=$('#studio-edges');if(!board||!svg)return;const w=board.clientWidth,h=board.clientHeight;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML=appState.studio.edges.map(edge=>{const a=appState.studio.nodes.find(n=>n.id===edge.from),b=appState.studio.nodes.find(n=>n.id===edge.to);if(!a||!b)return '';const x1=a.x+166,y1=a.y+39,x2=b.x,y2=b.y+39,mid=(x1+x2)/2;return `<path d="M${x1} ${y1} C${mid} ${y1} ${mid} ${y2} ${x2} ${y2}" fill="none" stroke="#62baf5" stroke-width="2"/><circle cx="${x2}" cy="${y2}" r="4" fill="#64c0f1"/>`}).join('')}
function wouldCreateCycle(from,to){const edges=[...appState.studio.edges,{from,to}];const seen=new Set();function visit(n){if(n===from)return true;if(seen.has(n))return false;seen.add(n);return edges.filter(e=>e.from===n).some(e=>visit(e.to))}return visit(to)}
function addStudioModule(type,x=null,y=null){const palette=modulePalette.find(m=>m.id===type);if(!palette)return;const g=appState.studio,id='node-'+Math.random().toString(36).slice(2,10);g.nodes.push({id,type,label:palette.name,x:x??(70+(g.nodes.length%3)*210),y:y??(95+Math.floor(g.nodes.length/3)*120)});g.selected=id;render()}
function studioDragHandlers(){const board=$('#studio-board');if(!board)return;board.addEventListener('dragover',e=>e.preventDefault());board.addEventListener('drop',e=>{e.preventDefault();const type=e.dataTransfer.getData('text/plain');const rect=board.getBoundingClientRect();addStudioModule(type,Math.max(0,Math.min(rect.width-173,e.clientX-rect.left-75)),Math.max(35,Math.min(rect.height-90,e.clientY-rect.top-40)))});document.querySelectorAll('.palette-item').forEach(el=>el.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',el.dataset.module)));board.querySelectorAll('[data-studio-node]').forEach(el=>{let down=false,sx,sy,startX,startY;el.addEventListener('pointerdown',e=>{if(e.target.classList.contains('port'))return;const n=appState.studio.nodes.find(n=>n.id===el.dataset.studioNode);if(!n)return;down=true;sx=e.clientX;sy=e.clientY;startX=n.x;startY=n.y;el.setPointerCapture(e.pointerId);appState.studio.selected=n.id;el.classList.add('selected')});el.addEventListener('pointermove',e=>{if(!down)return;const n=appState.studio.nodes.find(n=>n.id===el.dataset.studioNode);const rect=board.getBoundingClientRect();n.x=Math.max(0,Math.min(rect.width-168,startX+e.clientX-sx));n.y=Math.max(33,Math.min(rect.height-85,startY+e.clientY-sy));el.style.left=n.x+'px';el.style.top=n.y+'px';drawStudioEdges()});el.addEventListener('pointerup',()=>{if(down){down=false;const details=$('.studio-details');if(details)details.innerHTML=`Selected: <b>${esc(appState.studio.nodes.find(n=>n.id===el.dataset.studioNode)?.label||'')}</b>. ${button('remove-studio-node',`${icon('trash',13)} Remove`,'danger sm')}`}})})}
async function loadStudioExecution(id){
 appState.executionRunId=id;
 appState.execution=null;
 if(!id){render();return}
 await updateStudioExecution();
 render();
}
async function updateStudioExecution(){
 if(!appState.executionRunId)return;
 const id=appState.executionRunId;
 const [snapshot,run]=await Promise.all([api('/runs/'+id+'/execution'),api('/runs/'+id)]);
 appState.execution=snapshot;
 const idx=appState.runs.findIndex(r=>r.id===id);
 if(idx>=0)appState.runs[idx]=run;
}
async function downloadRunFile(runId,path){
 const res=await fetch(`/api/runs/${encodeURIComponent(runId)}/artifacts/${path.split('/').map(encodeURIComponent).join('/')}`,{headers:{Authorization:'Bearer '+appState.token}});
 if(!res.ok)throw new Error('Output download failed');
 const blob=await res.blob(), url=URL.createObjectURL(blob), a=document.createElement('a');
 a.href=url;a.download=path.split('/').pop();document.body.appendChild(a);a.click();a.remove();
 setTimeout(()=>URL.revokeObjectURL(url),5000);
}
async function showRun(id){try{appState.runDetail=await api('/runs/'+id);appState.runLog='';appState.runLogOffset=0;appState.artifacts=await api('/runs/'+id+'/artifacts');await refreshRunLog();render()}catch(e){notify(e.message,true)}}
async function refreshRunLog(){if(!appState.runDetail)return;try{const [r,log,arts]=await Promise.all([api('/runs/'+appState.runDetail.id),api('/runs/'+appState.runDetail.id+'/logs?offset='+appState.runLogOffset),api('/runs/'+appState.runDetail.id+'/artifacts')]);appState.runDetail=r;appState.runLog+=log.content;appState.runLogOffset=log.next_offset;appState.artifacts=arts}catch(e){/* Background polling failures do not erase the view. */}}
async function fileBrowse(path=null){try{appState.picker.list=await api('/files'+(path?'?path='+encodeURIComponent(path):''));render()}catch(e){notify(e.message,true)}}
async function downloadArtifact(name){try{await downloadRunFile(appState.runDetail.id,name)}catch(e){notify(e.message,true)}}
async function validateWizardSamples(){const w=appState.wizard;const result=await api('/experiments/validate',{method:'POST',body:{name:w.name||'Experiment',assay:w.assay||'Generic',samples:w.samples}});w.validation=result;return result}
function wizardDefaults(p){return Object.fromEntries((p?.fields||[]).filter(f=>f.default!==undefined).map(f=>[f.name,f.default]))}
function addExampleSamples(){const roots=appState.system?.data_roots||[];const root=roots[0]||'';appState.wizard.samples=['Control','Treatment'].flatMap(group=>[1,2].map(rep=>({sample:`${group}_rep${rep}`,condition:group,replicate:rep,batch:'',file1:`${root}/${group}_rep${rep}_R1.fastq`,file2:'',metadata:{}})));appState.wizard.validation=null;render()}
function csvParse(text,delimiter){const rows=[];let field='',row=[],quotes=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quotes&&text[i+1]==='"'){field+='"';i++}else quotes=!quotes}else if(c===delimiter&&!quotes){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quotes){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x!==''))rows.push(row);row=[];field=''}else field+=c}row.push(field);if(row.some(x=>x!==''))rows.push(row);return rows}
async function csvImport(file){if(!file)return;try{const text=await file.text();const rows=csvParse(text,file.name.endsWith('.tsv')?'\t':',');if(rows.length<2)throw Error('CSV must have header and sample rows');const headers=rows.shift().map(x=>x.trim().toLowerCase());const samples=rows.map((cols,i)=>{const record=Object.fromEntries(headers.map((h,j)=>[h,cols[j]||'']));const standard=['sample','sample_id','condition','replicate','batch','file1','fastq_1','r1','file2','fastq_2','r2'];const metadata=Object.fromEntries(Object.entries(record).filter(([key])=>!standard.includes(key)));return {sample:record.sample||record.sample_id||`sample_${i+1}`,condition:record.condition||'Control',replicate:Number(record.replicate)||1,batch:record.batch||'',file1:record.file1||record.fastq_1||record.r1||'',file2:record.file2||record.fastq_2||record.r2||'',metadata};});appState.wizard.samples=samples;appState.wizard.validation=null;render();notify(`${samples.length} samples imported`)}catch(e){notify(e.message,true)}}
async function performAction(action,el){const id=el?.dataset.id;switch(action){
  case 'navigate': appState.route=el.dataset.route;appState.wizard=null;appState.runDetail=null;appState.modal=null;appState.picker=null;render();return;
  case 'refresh': await loadAll();render();notify('Live controller data refreshed');return;
  case 'theme':appState.theme=appState.theme==='dark'?'light':'dark';localStorage.setItem('bio-theme',appState.theme);document.documentElement.classList.toggle('light',appState.theme==='light');render();return;
  case 'logout':appState.token='';appState.initialized=false;sessionStorage.removeItem('bio-token');render();return;
  case 'discover':{const resp=await api('/nodes/discover',{method:'POST'});appState.nodes=resp.nodes;appState.data=await api('/dashboard');render();notify(`Discovery refreshed: ${Object.values(resp.scanned_sources).reduce((a,b)=>a+b,0)} observations from available sources`);return}
  case 'new-run':appState.runDetail=null;newWizard();return;
  case 'open-pipeline':newWizard(id);return;
  case 'experiment-run':newWizard(null,id);return;
  case 'edit-experiment':newExperiment(id);return;
  case 'registry-toggle':appState.registryOpen=!appState.registryOpen;if(appState.registryOpen&&!appState.registry){render();try{appState.registry=await api('/registry/pipelines')}catch(e){appState.registryOpen=false;throw e}}render();return;
  case 'registry-refresh':appState.registry=await api('/registry/pipelines?refresh=true');render();notify('Registry catalog updated');return;
  case 'registry-import':{if(!confirm(`Import ${id} from its public Git repository? This downloads executable workflow code; inspect it before running.`))return;const p=await api('/registry/import',{method:'POST',body:{pipeline_id:id,confirm_untrusted_code:true}});appState.pipelines=await api('/pipelines');render();notify('Imported '+p.name+' · review source before execution');return}
  case 'studio-design':appState.studioMode='design';render();return;
  case 'studio-execution':appState.studioMode='execution';if(!appState.executionRunId&&appState.runs.length){await loadStudioExecution(appState.runs[0].id)}else render();return;
  case 'studio-execution-refresh':await updateStudioExecution();render();return;
  case 'download-studio-output':await downloadRunFile(appState.executionRunId,el.dataset.path);return;
  case 'open-studio-run':if(appState.executionRunId)await showRun(appState.executionRunId);return;
  case 'import-pipeline':appState.modal={type:'import'};render();return;
  case 'manual-node':appState.modal={type:'manual'};render();return;
  case 'close-modal':case 'close-modal-overlay':appState.modal=null;render();return;
  case 'modal-submit':{
    const m=appState.modal;
    if(m.type==='import'){
      const path=$('#import-path')?.value?.trim();const name=$('#import-name')?.value?.trim();if(!path)throw Error('Provide a pipeline directory');const p=await api('/pipelines/import',{method:'POST',body:{path,name}});appState.pipelines=await api('/pipelines');notify('Imported '+p.name);
    }else {const hostname=$('#node-host')?.value?.trim(),address=$('#node-address')?.value?.trim()||'';if(!hostname)throw Error('Hostname is required');await api('/nodes/manual',{method:'POST',body:{hostname,address}});appState.nodes=await api('/nodes');notify('Candidate added to inventory (not enrolled)')}
    appState.modal=null;render();return;
  }
  case 'close-wizard':case 'close-drawer-overlay':appState.wizard=null;render();return;
  case 'select-w-pipeline':{const p=appState.pipelines.find(x=>x.id===id);appState.wizard.pipelineId=id;appState.wizard.name=p.name+' · '+new Date().toLocaleDateString();appState.wizard.params=wizardDefaults(p);render();return}
  case 'wizard-prev':appState.wizard.step=Math.max(0,appState.wizard.step-1);render();return;
  case 'wizard-next':{
    const w=appState.wizard;
    if(w.step===1){const validation=await validateWizardSamples();if(!validation.valid){render();notify('Fix sample manifest errors before continuing',true);return}}
    w.step=Math.min(4,w.step+1);render();return;
  }
  case 'add-sample':appState.wizard.samples.push({sample:`sample_${appState.wizard.samples.length+1}`,condition:'Control',replicate:1,batch:'',file1:'',file2:'',metadata:{}});appState.wizard.validation=null;render();return;
  case 'remove-sample':appState.wizard.samples.splice(Number(el.dataset.row),1);appState.wizard.validation=null;render();return;
  case 'add-demo':addExampleSamples();return;
  case 'validate-samples':{const result=await validateWizardSamples();render();notify(result.valid?'All sample paths verified':`${result.errors.length} sample validation errors`,!result.valid);return}
  case 'pick-file':appState.picker={row:Number(el.dataset.row),field:el.dataset.field,list:null};await fileBrowse();return;
  case 'browse-dir':await fileBrowse(el.dataset.path);return;
  case 'select-file':{const pick=appState.picker;if(appState.wizard?.samples?.[pick.row]){appState.wizard.samples[pick.row][pick.field]=el.dataset.path;appState.wizard.validation=null}appState.picker=null;render();return}
  case 'close-picker':case 'close-picker-overlay':appState.picker=null;render();return;
  case 'restore-params':appState.wizard.params=wizardDefaults(selectedPipeline());render();return;
  case 'save-preset':{const name=prompt('Preset name');if(!name)return;await api('/presets',{method:'POST',body:{pipeline_id:appState.wizard.pipelineId,name,parameters:appState.wizard.params}});notify('Parameter preset saved');return}
  case 'save-experiment':{
    const w=appState.wizard;if(!w.name.trim())throw Error('Experiment name required');const body={name:w.name,assay:w.assay||'Generic',samples:w.samples};const path=w.experimentId?'/experiments/'+w.experimentId:'/experiments';const updated=await api(path,{method:w.experimentId?'PUT':'POST',body});appState.experiments=await api('/experiments');appState.wizard=null;appState.route='experiments';render();notify(`Experiment saved: ${updated.name}`);return;
  }
  case 'launch-run':{
    const w=appState.wizard,p=selectedPipeline();if(!w.name.trim())throw Error('Analysis name required');
    const result=await api('/runs',{method:'POST',body:{name:w.name,pipeline_id:p.id,experiment_id:w.experimentId||null,params:w.params,samples:w.samples,node_ids:['local-controller']}});
    appState.wizard=null;appState.route='runs';appState.runs=await api('/runs');render();notify('Analysis submitted to the local controller');await showRun(result.id);return;
  }
  case 'run-detail':await showRun(id);return;
  case 'close-run':case 'close-run-overlay':appState.runDetail=null;appState.runLog='';appState.runLogOffset=0;render();return;
  case 'view-studio-execution':{const id=appState.runDetail.id;appState.runDetail=null;appState.route='studio';appState.studioMode='execution';await loadStudioExecution(id);return}
  case 'cancel-run':{if(!confirm('Cancel this running analysis?'))return;await api('/runs/'+appState.runDetail.id+'/cancel',{method:'POST'});notify('Cancellation requested');await refreshRunLog();render();return}
  case 'download-artifact':await downloadArtifact(el.dataset.name);return;
  case 'add-module':addStudioModule(el.dataset.module);return;
  case 'connect-source':appState.studio.connectFrom=id;render();return;
  case 'connect-target':{const g=appState.studio;if(g.connectFrom&&g.connectFrom!==id&&!g.edges.some(e=>e.from===g.connectFrom&&e.to===id)){if(wouldCreateCycle(g.connectFrom,id))throw Error('Connection would create a cycle');g.edges.push({from:g.connectFrom,to:id})}g.connectFrom=null;render();return}
  case 'remove-studio-edge':{const index=Number(el.dataset.index);appState.studio.edges.splice(index,1);render();return}
  case 'remove-studio-node':{const g=appState.studio;g.nodes=g.nodes.filter(n=>n.id!==g.selected);g.edges=g.edges.filter(e=>e.from!==g.selected&&e.to!==g.selected);g.selected=null;render();return}
  case 'clear-graph':if(!confirm('Clear the current draft graph?'))return;appState.studio.nodes=[];appState.studio.edges=[];appState.studio.selected=null;render();return;
  case 'save-graph':{const g=appState.studio;if(!g.name.trim())throw Error('Give your workflow draft a name');const r=await api('/studio/graphs',{method:'POST',body:{name:g.name,nodes:g.nodes,edges:g.edges}});appState.graphs=await api('/studio/graphs');render();notify('Workflow draft saved (#'+r.id+')');return}
  case 'load-graph':{if(!appState.graphs.length)throw Error('No saved drafts available');const listing=appState.graphs.map(g=>`${g.id}: ${g.name}`).join('\n');const id=prompt('Enter saved draft ID:\n'+listing);if(!id)return;const g=appState.graphs.find(x=>String(x.id)===id.trim());if(!g)throw Error('Draft not found');appState.studio={name:g.name,nodes:structuredClone(g.nodes),edges:structuredClone(g.edges),selected:null,connectFrom:null};render();notify('Loaded '+g.name);return}
  default:return;
}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action?.endsWith('overlay')&&e.target!==el)return;try{await performAction(el.dataset.action,el)}catch(err){notify(err.message||String(err),true)} });
document.addEventListener('input',e=>{
 const t=e.target;
 if(t.matches('[data-sample]')&&appState.wizard){const n=Number(t.dataset.sample);if(appState.wizard.samples[n]){if(t.dataset.field.startsWith('metadata.')){appState.wizard.samples[n].metadata ??= {}; appState.wizard.samples[n].metadata[t.dataset.field.slice(9)]=t.value;}else appState.wizard.samples[n][t.dataset.field]=t.dataset.field==='replicate'?Number(t.value)||1:t.value;appState.wizard.validation=null}}
 if(t.matches('[data-w-field]')&&appState.wizard){appState.wizard[t.dataset.wField]=t.value}
 if(t.matches('[data-param]')&&appState.wizard){const f=selectedPipeline()?.fields?.find(x=>x.name===t.dataset.param);let value=t.type==='checkbox'?t.checked:t.value;if(f?.type==='integer')value=Number.parseInt(value,10);if(f?.type==='number')value=Number(value);appState.wizard.params[t.dataset.param]=value}
 if(t.matches('#studio-name'))appState.studio.name=t.value;
 if(t.matches('#registry-search')){appState.registryQuery=t.value;const cursor=t.selectionStart;const host=$('.registry-browser');if(host){host.outerHTML=registryCatalogPage();const next=$('#registry-search');next?.focus();next?.setSelectionRange(cursor,cursor)}}
 if(t.matches('#pipeline-search')){appState.search=t.value;const cursor=t.selectionStart;const focusInput=t;appState.route='pipelines';const main=$('.page');if(main)main.innerHTML=pipelinePage();const next=$('#pipeline-search');next?.focus();next?.setSelectionRange(cursor,cursor)}
 if(t.matches('[data-node-field="cpu_limit"]')){const label=t.closest('.node-alloc')?.querySelector('label strong');if(label){const node=appState.nodes.find(n=>n.id===t.dataset.node);label.textContent=t.value+(node?.cpu_total?' / '+node.cpu_total:'')}}
});
document.addEventListener('change',async e=>{
 const t=e.target;
 try{
  if(t.id==='studio-execution-run'){await loadStudioExecution(t.value);return}
  if(t.id==='csv-import'){await csvImport(t.files[0]);return}
  if(t.id==='w-select-experiment'){const ex=appState.experiments.find(x=>x.id===Number(t.value));if(ex){appState.wizard.samples=structuredClone(ex.samples);appState.wizard.experimentId=ex.id}else {appState.wizard.experimentId=null;appState.wizard.samples=[]}appState.wizard.validation=null;render();return}
  if(t.matches('[data-node-field]')){const id=t.dataset.node,field=t.dataset.nodeField,value=t.type==='checkbox'?t.checked:Number(t.value);const n=await api('/nodes/'+encodeURIComponent(id),{method:'PATCH',body:{[field]:value}});const idx=appState.nodes.findIndex(x=>x.id===id);if(idx>=0)appState.nodes[idx]=n;render();notify('Node policy saved (not scheduler-enforced)');return}
 }catch(err){notify(err.message,true);render()}
});
async function boot(){render();if(!appState.token)return;try{await loadAll();render()}catch(err){appState.initialized=false;render();notify(err.message,true)}}
setInterval(async()=>{
 if(!appState.token||!appState.initialized)return;
 try{
  if(appState.route==='studio'&&appState.studioMode==='execution'&&appState.executionRunId){await updateStudioExecution();render()}
  if(appState.runDetail){await refreshRunLog();render();const el=$('#run-log');if(el)el.scrollTop=el.scrollHeight}
  if(['dashboard','runs'].includes(appState.route)&&!appState.wizard&&!appState.picker&&!appState.modal){const [d,r]=await Promise.all([api('/dashboard'),api('/runs')]);appState.data=d;appState.runs=r;if(d.controller?.details?.cpu_percent!==undefined)appState.cpuHistory=[...appState.cpuHistory.slice(-23),d.controller.details.cpu_percent];if(!appState.runDetail)render()}
 }catch(err){/* Keep existing information visible if a poll fails. */}
},4000);
boot();
